def blend(rgb,mask,color):
    result=rgb.copy();result[mask]=(result[mask]*.45+np.array(color)*.55).astype('uint8');return Image.fromarray(result)
def panel(q,iid):
    qid=q['query_id'];rgb=np.array(Image.open(base/qid/iid/'original_rgb.png'));reference=np.array(Image.open(base/qid/iid/'mask.png'))>0;ref=refs[qid,iid];canvas=Image.new('RGB',(3000,390),'#14212b');d=ImageDraw.Draw(canvas);description=f'{qid} | {q["query_en"]} | {iid}'
    d.text((12,6),description,font=font,fill='white');d.text((12,34),'SAM-assisted Pseudo-GT; Codex reviewed, NOT human ground truth. '+('COMMON EXCLUSION: reference unreliable' if ref['status']!='accepted_pseudo' else 'Evaluated reference; fixed predictions, no retraining'),font=small,fill='#ffcc66' if ref['status']!='accepted_pseudo' else '#b8c9d5')
    images=[Image.fromarray(rgb),blend(rgb,reference,[20,235,90])];labels=['Original RGB','Reference Mask'+(' [EXCLUDED]' if ref['status']!='accepted_pseudo' else '')]
    for method,name in zip(mids,names):
        mask=np.array(Image.open(ROOT/'outputs'/method/qid/iid/'mask.png'))>0;images.append(blend(rgb,mask,[255,30,15]));r=byview[method,qid,iid];labels.append(name+' | IoU '+(f"{r['iou']*100:.2f}%" if r['status']=='evaluated' else 'N/A (excluded)'))
    for i,(im,label) in enumerate(zip(images,labels)):
        d.text((i*500+8,68),label,font=font,fill='white');canvas.paste(im.resize((500,282),Image.Resampling.LANCZOS),(i*500,102))
    return canvas
